export const THEMES={garden:{name:'自然庭院',description:'轻风、鸟鸣与清脆提示'},mechanical:{name:'机械工坊',description:'电机低鸣、齿轮节拍与金属提示'},digital:{name:'电子控制室',description:'合成脉冲与短促电子提示'},soft:{name:'柔和提示',description:'轻柔和声与低音背景'}};
export const DEFAULTS={enabled:true,theme:'garden',volume:.65,channels:{start:{enabled:true,volume:.7},end:{enabled:true,volume:.7},ambient:{enabled:true,volume:.4},detail:{enabled:true,volume:.4}}};
const bounded=(v,d)=>Number.isFinite(v)?Math.max(0,Math.min(1,v)):d;
export function normalizeSettings(raw={}){if(!raw||typeof raw!=='object'||Array.isArray(raw))raw={};const s=structuredClone(DEFAULTS);s.enabled=typeof raw.enabled==='boolean'?raw.enabled:s.enabled;s.theme=THEMES[raw.theme]?raw.theme:s.theme;s.volume=bounded(raw.volume,s.volume);for(const k of Object.keys(s.channels)){const v=raw.channels?.[k]||{};s.channels[k]={enabled:typeof v.enabled==='boolean'?v.enabled:s.channels[k].enabled,volume:bounded(v.volume,s.channels[k].volume)};}return s;}
export class TownAudio{
 constructor({storage=globalThis.localStorage,contextFactory=()=>new (globalThis.AudioContext||globalThis.webkitAudioContext)()}={}){this.storage=storage;this.contextFactory=contextFactory;this.key='agent-town-audio-v1';let saved;try{saved=JSON.parse(storage?.getItem(this.key)||'{}');}catch{}this.settings=normalizeSettings(saved);this.ctx=null;this.channel='detail';this.voices=new Set();this.loops=[];this.timer=0;this.visible=true;this.previewUntil=0;}
 init(){if(!this.settings.enabled)return false;if(this.ctx){if(this.ctx.state==='suspended')this.ctx.resume()?.catch(()=>{});return true;}try{this.ctx=this.contextFactory();const c=this.ctx;this.master=c.createGain();this.master.gain.value=0;const limiter=c.createDynamicsCompressor();limiter.threshold.value=-16;limiter.ratio.value=6;this.master.connect(limiter);limiter.connect(c.destination);this.buses={};for(const k of Object.keys(this.settings.channels)){const gain=c.createGain();gain.gain.value=0;gain.connect(this.master);this.buses[k]=gain;}this.ambience=c.createGain();this.ambience.gain.value=0;this.ambience.connect(this.buses.ambient);const buffer=c.createBuffer(1,c.sampleRate*2,c.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.noise=buffer;this.buildAmbient();this.apply();return true;}catch{this.ctx=null;return false;}}
 apply(){if(!this.ctx)return;const t=this.ctx.currentTime;this.master.gain.setTargetAtTime(this.settings.enabled&&this.visible?this.settings.volume:0,t,.025);for(const [k,v]of Object.entries(this.settings.channels))this.buses[k].gain.setTargetAtTime(v.enabled?v.volume:0,t,.025);}
 update(patch){const old=this.settings.theme;this.settings=normalizeSettings({...this.settings,...patch,channels:{...this.settings.channels,...patch.channels}});try{this.storage?.setItem(this.key,JSON.stringify(this.settings));}catch{}if(this.ctx&&old!==this.settings.theme)this.buildAmbient();this.apply();}
 setVisible(visible){this.visible=visible;this.apply();}
 withChannel(channel,callback){const old=this.channel;this.channel=channel;try{return callback();}finally{this.channel=old;}}
 allowed(channel){return !!this.ctx&&this.visible&&this.settings.enabled&&this.settings.volume>0&&this.settings.channels[channel]?.enabled&&this.settings.channels[channel].volume>0;}
 output(channel,pan=0){if(!pan||!this.ctx.createStereoPanner)return {node:this.buses[channel],cleanup:()=>{}};const p=this.ctx.createStereoPanner();p.pan.value=Math.max(-.8,Math.min(.8,pan));p.connect(this.buses[channel]);return {node:p,cleanup:()=>p.disconnect()};}
 tone(freq,duration,volume=.1,type='sine',delay=0,slide=0,pan=0,channel=this.channel){if(!this.allowed(channel))return;const theme=this.settings.theme;if(channel!=='ambient'){if(theme==='mechanical'){freq*=.55;type='triangle';duration=Math.min(duration,.23);}else if(theme==='digital'){freq*=1.1;type='square';volume*=.35;duration=Math.min(duration,.2);}else if(theme==='soft'){freq*=.75;type='sine';volume*=.65;duration*=1.25;}}
 const c=this.ctx,t=c.currentTime+delay,o=c.createOscillator(),g=c.createGain(),out=this.output(channel,pan);o.type=type;o.frequency.setValueAtTime(Math.max(30,freq),t);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,slide),t+duration);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,volume),t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(out.node);this.voices.add(o);o.onended=()=>{o.disconnect();g.disconnect();out.cleanup();this.voices.delete(o);};o.start(t);o.stop(t+duration+.03);}
 hiss(duration,volume=.08,freq=2500,q=.8,delay=0,pan=0,type='bandpass'){const channel=this.channel;if(!this.allowed(channel))return;if(this.settings.theme!=='garden'){this.tone(this.settings.theme==='mechanical'?180:440,Math.min(duration,.15),volume*.5,'triangle',delay,0,pan,channel);return;}const c=this.ctx,t=c.currentTime+delay,src=c.createBufferSource(),filter=c.createBiquadFilter(),g=c.createGain(),out=this.output(channel,pan);src.buffer=this.noise;filter.type=type;filter.frequency.value=freq;filter.Q.value=q;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(volume,t+.04);g.gain.exponentialRampToValueAtTime(.0001,t+duration);src.connect(filter);filter.connect(g);g.connect(out.node);this.voices.add(src);src.onended=()=>{src.disconnect();filter.disconnect();g.disconnect();out.cleanup();this.voices.delete(src);};src.start(t);src.stop(t+duration+.03);}
 buildAmbient(){const c=this.ctx,t=c.currentTime;for(const {src,g,filter} of this.loops){g.gain.setTargetAtTime(0,t,.025);src.stop(t+.12);src.onended=()=>{src.disconnect();g.disconnect();filter?.disconnect();};}this.loops=[];this.timer=0;
 const add=(freq,volume,type='sine',noise=false)=>{const src=noise?c.createBufferSource():c.createOscillator(),g=c.createGain();g.gain.value=volume;let filter;if(noise){src.buffer=this.noise;src.loop=true;filter=c.createBiquadFilter();filter.type='lowpass';filter.frequency.value=freq;src.connect(filter);filter.connect(g);}else{src.type=type;src.frequency.value=freq;src.connect(g);}g.connect(this.ambience);src.start();this.loops.push({src,g,filter});};
 if(this.settings.theme==='garden')add(380,.07,'sine',true);else if(this.settings.theme==='mechanical'){add(52,.023,'triangle');add(104,.009);}else if(this.settings.theme==='digital'){add(98,.014);add(196,.006);}else{add(110,.012);add(164.81,.008);}}
 tick(dt,{running=true,wind=0,energy=0,night=false}={}){if(!this.ctx)return;const c=this.ctx,live=this.visible&&(running||c.currentTime<this.previewUntil);this.ambience.gain.setTargetAtTime(live?(.75+Math.min(1,Math.abs(wind))*.15+Math.min(1,energy)*.1):0,c.currentTime,.2);this.timer-=dt;if(!live||!this.allowed('ambient')||this.timer>0)return;
 if(this.settings.theme==='garden'){if(!night){this.tone(2450,.09,.022,'sine',0,3100,-.3,'ambient');this.tone(2800,.1,.018,'sine',.15,2200,.3,'ambient');}else this.tone(3600,.06,.009,'sine',0,0,.2,'ambient');this.timer=night?5:7+Math.random()*4;}
 else if(this.settings.theme==='mechanical'){this.tone(420,.035,.022,'triangle',0,170,0,'ambient');this.timer=.55;}
 else if(this.settings.theme==='digital'){this.tone(330,.08,.015,'sine',0,440,0,'ambient');this.timer=2.5;}else this.timer=5;}
 preview(channel){if(!this.init()||!this.allowed(channel))return false;if(channel==='ambient'){this.previewUntil=this.ctx.currentTime+3;return true;}this.withChannel(channel,()=>{if(channel==='start'){this.tone(520,.16,.09,'sine',0,880);this.tone(780,.17,.06,'sine',.18);}else{this.tone(660,.3,.07);this.tone(880,.4,.07,'sine',.12);this.tone(1320,.45,.05,'sine',.25);}});return true;}
 dispose(){for(const v of this.voices){try{v.stop();}catch{}}for(const l of this.loops){try{l.src.stop();}catch{}l.src.disconnect();l.g.disconnect();l.filter?.disconnect();}this.voices.clear();this.loops=[];this.ctx?.close?.();this.ctx=null;}
}
